    descriptionAdvanced: {
      de: "Der Baiterek-Turm, ein Symbol des modernen Nur-Sultan (Astana), ist mehr als nur ein Aussichtsturm. Entworfen, um einen Volksmythos zu verkörpern, stellt die Struktur den Baum des Lebens dar, in dessen Krone der magische Vogel Samruk sein goldenes Ei gelegt hat. Besucher können mit einem Aufzug zur 97 Meter hohen Aussichtsplattform fahren – eine Zahl, die das Jahr 1997 symbolisiert, in dem Astana zur Hauptstadt Kasachstans wurde. Oben angekommen, bietet sich ein atemberaubender Panoramablick über die futuristische Stadt. Eine besondere Attraktion ist eine vergoldete Handabformung von Nursultan Nasarbajew, dem ersten Präsidenten Kasachstans. Es heißt, wer seine Hand in den Abdruck legt und sich etwas wünscht, dessen Wunsch wird in Erfüllung gehen. Der Turm ist ein unverzichtbares Erlebnis, das die Ambitionen und die reiche Kultur des modernen Kasachstans widerspiegelt.",
      hu: "A Bajterek-torony Nur-Szultan (Asztana) modern szimbóluma, amely több mint egy egyszerű kilátó. A tervezés alapja egy népi mítosz, amely az élet fáját ábrázolja, melynek koronájába Szamruk, a varázslatos madár rakta aranytojását. A látogatók lifttel juthatnak fel a 97 méter magas kilátóteraszra – ez a szám 1997-et szimbolizálja, amikor Asztana lett Kazahsztán fővárosa. Fentről lélegzetelállító panoráma nyílik a futurisztikus városra. Különleges látványosság Nurszultan Nazarbajev, Kazahsztán első elnökének aranyozott kézlenyomata. A hiedelem szerint, aki a kezét a lenyomatba helyezi és kíván valamit, annak a kívánsága teljesül. A torony kihagyhatatlan élmény, amely tükrözi a modern Kazahsztán törekvéseit és gazdag kultúráját.",
      ro: "Turnul Bayterek, un simbol al modernului Nur-Sultan (Astana), este mai mult decât un simplu turn de observație. Proiectat pentru a întruchipa un mit popular, structura reprezintă Arborele Vieții, în coroana căruia pasărea magică Samruk și-a depus oul de aur. Vizitatorii pot urca cu un lift la platforma de observare de 97 de metri înălțime – un număr care simbolizează anul 1997, când Astana a devenit capitala Kazahstanului. Odată ajunși sus, se deschide o vedere panoramică uluitoare asupra orașului futurist. O atracție specială este o amprentă aurită a mâinii lui Nursultan Nazarbayev, primul președinte al Kazahstanului. Se spune că oricine își pune mâna în amprentă și își pune o dorință, aceasta i se va împlini. Turnul este o experiență de neratat, reflectând ambițiile și cultura bogată a Kazahstanului modern.",
      en: "The Bayterek Tower, a symbol of modern Nur-Sultan (Astana), is more than just an observation tower. Designed to embody a folk myth, the structure represents the Tree of Life, in whose crown the magical bird Samruk has laid its golden egg. Visitors can take an elevator to the 97-meter-high observation deck – a number symbolizing the year 1997, when Astana became the capital of Kazakhstan. Once at the top, a breathtaking panoramic view of the futuristic city unfolds. A special attraction is a gilded handprint of Nursultan Nazarbayev, the first president of Kazakhstan. It is said that whoever places their hand in the print and makes a wish will have it come true. The tower is an unmissable experience that reflects the ambitions and rich culture of modern Kazakhstan.",
      es: "La Torre Baiterek, símbolo de la Astaná moderna, es mucho más que un mirador. Diseñada para encarnar un mito popular, la estructura representa el Árbol de la Vida, en cuya copa el ave mágica Samruk puso su huevo de oro. Los visitantes pueden subir en ascensor a la plataforma de observación de 97 metros de altura, cifra que simboliza el año 1997, cuando Astaná se convirtió en capital. Desde arriba se disfruta de una vista panorámica impresionante de la ciudad futurista. Una atracción especial es la huella de la mano dorada de Nursultán Nazarbáyev, el primer presidente de Kazajistán. Se dice que quien ponga su mano en la huella y pida un deseo, este se cumplirá. La torre refleja las ambiciones y la rica cultura del Kazajistán moderno.",
      pt: "A Torre Baiterek, símbolo da moderna Astana, é mais do que apenas uma torre de observação. Projetada para personificar um mito popular, a estrutura representa a Árvore da Vida, em cuja copa a ave mágica Samruk depositou o seu ovo de ouro. Os visitantes podem subir de elevador até à plataforma de observação a 97 metros de altura – um número que simboliza o ano de 1997, em que Astana se tornou a capital do Cazaquistão. Do topo, desfruta-se de uma vista panorâmica deslumbrante sobre a cidade futurista. Uma atração especial é a impressão da mão dourada de Nursultan Nazarbayev, o primeiro presidente. Diz a lenda que quem colocar a sua mão na impressão e fizer um desejo, verá o seu desejo realizado.",
      fr: "Symbole de la modernité d'Astana, la tour Bayterek est bien plus qu'un simple belvédère. Son architecture incarne un mythe populaire : l'Arbre de Vie au sommet duquel l'oiseau magique Samrouk a déposé un œuf d'or. Les visiteurs accèdent par ascenseur à une plateforme d'observation située à 97 mètres de haut, un chiffre symbolisant l'année 1997, date à laquelle Astana devint la capitale. De là, on jouit d'un panorama époustouflant sur cette cité futuriste. Une attraction insolite y attend les curieux : l'empreinte dorée de la main de Noursoultan Nazarbaïev, premier président du pays. La tradition veut que si l'on y place sa main en faisant un vœu, celui-ci s'exauce. Cette tour reflète les ambitions et la culture vibrante du Kazakhstan d'aujourd'hui.",
    },
