      en: "A vast and modern museum complex showcasing the rich history, culture, and art of the Kazakh nation from ancient times to the present.",
      es: "Un moderno complejo museístico que presenta la rica historia, cultura y arte de la nación kazaja desde la antigüedad hasta la actualidad.",
      pt: "Um enorme e moderno complexo museológico que apresenta a rica história, cultura e arte da nação cazaque, desde a Antiguidade até aos dias de hoje.",
