    facts: {
      de: [
        "Es ist das größte Museum in ganz Zentralasien.",
        "Zu den Höhepunkten gehört die Halle des Goldes mit Artefakten skythischer Nomaden."
      ],
      hu: [
        "Ez a legnagyobb múzeum egész Közép-Ázsiában.",
        "A kiemelkedő látnivalók közé tartozik az Aranyterem, amely a szkíta nomádok leleteit mutatja be."
      ],
      ro: [
        "Este cel mai mare muzeu din toată Asia Centrală.",
        "Punctele de atracție includ Sala Aurului cu artefacte ale nomazilor sciți."
      ],
      en: [
        "It is the largest museum in all of Central Asia.",
        "Highlights include the Hall of Gold featuring artifacts from Scythian nomads."
      ],
      es: ["Es el museo más grande de toda Asia Central.", "Entre lo más destacado figura el Salón del Oro con artefactos de nómadas escitas."],
      pt: ["É o maior museu de toda a Ásia Central.", "Um dos destaques é o Salão do Ouro com artefactos de nómadas citas."],
      fr: ["C'est le plus grand musée de toute l'Asie centrale.", "Parmi les points forts figure la salle de l'or avec des artefacts des nomades scythes."],
    }, image: "/poi-images/national-museum-kazakhstan-landmarks-v2.webp",
    descriptionAdvanced: {
      de: "Das Nationalmuseum der Republik Kasachstan in Nur-Sultan (Astana) ist das größte und modernste Museum in Zentralasien. Es wurde 2014 eröffnet und bietet einen umfassenden Überblick über die reiche Geschichte und Kultur des Landes, von der Antike bis in die moderne Ära. Die Architektur des Museums ist einzigartig, mit einer Fassade aus blauem Glas, die an die kasachische Flagge erinnert. Auf einer Fläche von 74.000 Quadratmetern beherbergt es mehrere thematische Hallen. Die Halle des Goldes ist ein besonderer Höhepunkt und zeigt Tausende von Goldartefakten skythischer Nomaden, darunter eine Replik des berühmten 'Goldenen Mannes'. Weitere Hallen widmen sich der Ethnographie, der mittelalterlichen Geschichte, dem modernen Kasachstan und der zeitgenössischen Kunst. Interaktive Displays, Multimedia-Installationen und großformatige Exponate machen den Museumsbesuch zu einem fesselnden Erlebnis für alle Altersgruppen. Es ist eine unverzichtbare Institution zum Verständnis der kasachischen Identität.",
      hu: "A Kazah Köztársaság Nemzeti Múzeuma Nur-Szultanban (Asztana) Közép-Ázsia legnagyobb és legmodernebb múzeuma. A 2014-ben megnyitott múzeum átfogó áttekintést nyújt az ország gazdag történelméről és kultúrájáról az ókortól a modern korig. A múzeum építészete egyedi, kék üveghomlokzata a kazah zászlóra emlékeztet. 74 000 négyzetméteren több tematikus teremnek ad otthont. Az Aranyterem különleges fénypont, ahol több ezer aranytárgyat állítanak ki a szaka nomádoktól, köztük a híres 'Aranyember' másolatát. Más termek a néprajzzal, a középkori történelemmel, a modern Kazahsztánnal és a kortárs művészettel foglalkoznak. Interaktív kijelzők, multimédiás installációk és nagyméretű kiállítási tárgyak teszik a múzeumlátogatást lebilincselő élménnyé minden korosztály számára. A kazah identitás megértéséhez nélkülözhetetlen intézmény.",
      ro: "Muzeul Național al Republicii Kazahstan din Nur-Sultan (Astana) este cel mai mare și mai modern muzeu din Asia Centrală. Inaugurat în 2014, acesta oferă o imagine de ansamblu cuprinzătoare asupra istoriei și culturii bogate a țării, din antichitate până în epoca modernă. Arhitectura muzeului este unică, cu o fațadă de sticlă albastră care amintește de steagul kazah. Pe o suprafață de 74.000 de metri pătrați, acesta găzduiește mai multe săli tematice. Sala Aurului este un punct de atracție deosebit, expunând mii de artefacte din aur ale nomazilor sciți, inclusiv o replică a faimosului 'Om de Aur'. Alte săli sunt dedicate etnografiei, istoriei medievale, Kazahstanului modern și artei contemporane. Ecranele interactive, instalațiile multimedia și exponatele de mari dimensiuni fac din vizita la muzeu o experiență captivantă pentru toate vârstele. Este o instituție esențială pentru înțelegerea identității kazahe.",
      en: "The National Museum of the Republic of Kazakhstan in Nur-Sultan (Astana) is the largest and most modern museum in Central Asia. Opened in 2014, it provides a comprehensive overview of the country's rich history and culture, from ancient times to the modern era. The museum's architecture is unique, with a blue glass facade reminiscent of the Kazakh flag. Covering an area of 74,000 square meters, it houses several thematic halls. The Hall of Gold is a particular highlight, displaying thousands of gold artifacts from Scythian nomads, including a replica of the famous 'Golden Man'. Other halls are dedicated to ethnography, medieval history, modern Kazakhstan, and contemporary art. Interactive displays, multimedia installations, and large-scale exhibits make a visit to the museum an engaging experience for all ages. It is an essential institution for understanding the Kazakh identity.",
      es: "El Museo Nacional de la República de Kazajistán en Astaná es el más grande y moderno de Asia Central. Inaugurado en 2014, ofrece una visión exhaustiva de la historia del país. Su arquitectura destaca por una fachada de vidrio azul que evoca la bandera nacional. En sus 74.000 metros cuadrados alberga salas temáticas como el Salón del Oro, con artefactos escitas que incluyen una réplica del 'Hombre de Oro'. Otras salas cubren etnografía, historia medieval y arte contemporáneo. El uso de pantallas interactivas y multimedia hace de la visita una experiencia cautivadora para comprender la identidad kazaja.",
      pt: "O Museu Nacional da República do Cazaquistão em Nur-Sultan (Astana) é o maior e mais moderno museu da Ásia Central. Inaugurado em 2014, oferece uma visão abrangente da rica história e cultura do país, desde a Antiguidade até à era moderna. A arquitetura do museu é única, com uma fachada de vidro azul que lembra a bandeira cazaque. Numa área de 74.000 metros quadrados, abriga várias salas temáticas. O Salão do Ouro é um destaque especial, exibindo milhares de artefactos de ouro de nómadas citas, incluindo uma réplica do famoso 'Homem de Ouro'. Instalações multimédia tornam a visita uma experiência envolvente.",
      fr: "Le Musée national de la République du Kazakhstan à Nur-Sultan (Astana) est le plus grand et le plus moderne musée d'Asie centrale. Inauguré en 2014, il offre un aperçu complet de la riche histoire et de la culture du pays, de l'Antiquité à l'époque moderne. L'architecture du musée est unique, avec une façade en verre bleu rappelant le drapeau kazakh. Sur une surface de 74 000 mètres carrés, il abrite plusieurs salles thématiques. La salle de l'or est un point fort particulier, présentant des milliers d'artefacts en or des nomades scythes, dont une réplique du célèbre 'Homme d'Or'. Des installations multimédias font de la visite une expérience captivante.",
    },
