      en: ["Base elevation: 2,260 meters (7,410 ft).", "Top elevation: 3,200 meters (10,500 ft).", "The resort has about 20 km of ski slopes.", "The main gondola connects Medeu to the resort base.", "The ski season typically runs from November to April.", "It features a 'Snow Park' for freestyle skiing and snowboarding.", "The resort is known for its relatively mild climate."],
