      fr: ["Altitude de base : 2 260 mètres (7 410 pieds).", "Altitude au sommet : 3 200 mètres (10 500 pieds).", "Le domaine skiable compte environ 20 km de pistes.", "La télécabine principale relie Medeo à la station de base.", "La saison de ski dure généralement de novembre à avril.", "Elle dispose d'un 'Snow Park' pour le ski freestyle et le snowboard.", "La station est réputée pour son climat relativement doux."],
