      es: ["El edificio se inauguró en 2013 por iniciativa del presidente kazajo.", "La sala principal tiene capacidad para más de 1.200 espectadores."],
      pt: ["O edifício foi inaugurado em 2013 por iniciativa do presidente cazaque.", "A sala principal tem capacidade para mais de 1.200 espectadores."],
