      hu: ["1999-ben nyílt meg.", "Kapacitás: akár 7000 hívő.", "A fő kék kupola 20 méter átmérőjű és 36 méter magas.", "Az öt minaret közül a legmagasabb 47 méter magas.", "A mecset fehér márványból épült.", "Egy régebbi, 1890-ben épült mecsetet váltott fel.", "A kupolát török kalligráfusok Korán-szúrái díszítik.", "Kazahsztán egyik legnagyobb mecsetje."],
      ro: ["Deschisă în 1999.", "Capacitate: până la 7.000 de credincioși.", "Cupola principală albastră are un diametru de 20 de metri și o înălțime de 36 de metri.", "Cel mai înalt dintre cele cinci minarete are 47 de metri înălțime.", "Moscheea este construită din marmură albă.", "A înlocuit o moschee mai veche, construită în 1890.", "Cupola este decorată cu sure din Coran de caligrafi turci.", "Este una dintre cele mai mari moschei din Kazahstan."],
      en: ["Opened in 1999.", "Capacity: up to 7,000 worshippers.", "The main blue dome is 20 meters in diameter and 36 meters high.", "The tallest of the five minarets is 47 meters high.", "The mosque is built of white marble.", "It replaced an older mosque that was built in 1890.", "The dome is decorated with surahs from the Quran by Turkish calligraphers.", "It is one of the largest mosques in Kazakhstan."],
      es: ["Inaugurada en 1999.", "Capacidad: hasta 7.000 personas.", "La cúpula azul principal tiene 20 metros de diámetro y 36 metros de altura.", "El minarete más alto de los cinco mide 47 metros.", "Construida íntegramente en mármol blanco.", "Reemplazó a una mezquita anterior construida en 1890.", "La cúpula está decorada con suras del Corán por calígrafos turcos.", "Es una de las mezquitas más grandes de Kazajistán."],
      pt: ["Inaugurada em 1999.", "Capacidade: até 7.000 fiéis.", "A cúpula azul principal tem 20 metros de diâmetro e 36 metros de altura.", "O mais alto dos cinco minaretes tem 47 metros de altura.", "A mesquita é construída em mármore branco.", "Substituiu uma mesquita mais antiga construída em 1890.", "A cúpula está decorada com suras do Alcorão por calígrafos turcos.", "É uma das maiores mesquitas do Cazaquistão."],
      fr: ["Ouverte en 1999.", "Capacité : jusqu'à 7 000 fidèles.", "Le dôme principal bleu a un diamètre de 20 mètres et une hauteur de 36 mètres.", "Le plus haut des cinq minarets mesure 47 mètres de haut.", "La mosquée est construite en marbre blanc.", "Elle a remplacé une mosquée plus ancienne construite en 1890.", "Le dôme est orné de sourates du Coran par des calligraphes turcs.", "C'est l'une des plus grandes mosquées du Kazakhstan."],
